<?php
 require_once(__DIR__.'/../init.php'); class system_setup { protected $db; public function readInstallations ($params = null) { $ret = []; $setupPath = realpath(__DIR__ . '/../../../..'); $services = $this->execute("wmic service get name,pathname,started /value"); if (empty($services)) return $ret; $count = preg_match_all('/Name=(.*)\W+PathName=(?|(?>"([^"]*)")|(\S+)).*\W+Started=([\w]*)/' , $services, $matches); if (!$count) return $ret; for ($i = 0; $i < $count; $i++) { $pathInfo = pathinfo($matches[2][$i]); $exe = $pathInfo['basename']; if ($exe !== 'httpd.exe') continue; $path = realpath($pathInfo['dirname'] . '/../../..'); if ($path == $setupPath) continue; if (!file_exists("$path/src/service/app/apps.json")) continue; $setupVersion = json_clean_decode(file_get_contents("$setupPath/version"))->server; $version = null; if (file_exists("$path/cfg")) { $status = 1; if (file_exists("$path/version")) { try { $version = json_clean_decode(file_get_contents("$path/version"))->server; } catch (Throwable $e) {} if (!isset($version) || compareVersions($version, $setupVersion) < 0) { $status = 2; } } else { $status = 2; } } else { $status = 0; } $serviceStatus = $matches[3][$i] === 'TRUE' ? 1 : 2; $inst = [ 'path' => $path, 'status' => $status, 'version' => $version, 'note' => 'Какой то комментарий', 'serviceName' => $matches[1][$i], 'serviceStatus' => $serviceStatus ]; $ret[] = $inst; } return $ret; } protected function execute ($command) { try { $res = executeCmd($command, $exitCode); } catch (Throwable $e) { throw new Exception("Ошибка выполнения команды \"$command\"!" . " Возможно в системе не установлен WMI (Windows Management Instumentation)."); } if ($exitCode != 0) { throw new Exception("Команда \"$command\" вернула код ошибки [$exitCode]!" . " Обратитесь к разработчику."); } return $res; } } handleJsonRpc('system_setup');